export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // key -> { value, expiresAt }
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined
      if (clock() > entry.expiresAt) {
        entries.delete(key)
        return undefined
      }

      // Map iteration order tracks recency: move a hit to the newest end.
      entries.delete(key)
      entries.set(key, entry)
      return entry.value
    },
    set(key, value) {
      const now = clock()
      if (entries.has(key)) entries.delete(key)
      if (entries.size >= capacity) {
        // The first key is the least-recently-used entry.
        const victim = entries.keys().next().value
        entries.delete(victim)
      }
      entries.set(key, { value, expiresAt: now + ttlMs })
    },

